def numberOfBeautifulIntegers(low: int, high: int, k: int):
    from functools import lru_cache

    def count_beautiful(n):
        if n < 0:
            return 0
        digits = list(map(int, str(n + 1)))  # count numbers from 0 to n

        @lru_cache(maxsize=None)
        def dfs(pos, even, odd, mod, started):
            if pos == len(digits):
                if not started:
                    return 0
                return 1 if even == odd and mod == 0 else 0
            limit = digits[pos] if started else 9
            total = 0
            for d in range(limit + 1):
                if not started and d == 0:
                    total += dfs(pos + 1, 0, 0, 0, False)
                else:
                    new_even = even + (1 if d % 2 == 0 else 0)
                    new_odd = odd + (1 if d % 2 != 0 else 0)
                    new_mod = (mod * 10 + d) % k
                    total += dfs(pos + 1, new_even, new_odd, new_mod, True)
            return total

        return dfs(0, 0, 0, 0, False)

    return count_beautiful(high) - count_beautiful(low - 1)
