def numberOfPermutations(n: int, requirements: List[List[int]]) -> int:
    MOD = 10**9 + 7

    # Create an array of required inversion counts for each prefix length
    req_inv = [-1] * n
    for end, cnt in requirements:
        req_inv[end] = cnt

    # dp[j] = number of ways to form current prefix with exactly j inversions
    dp = [1]  # dp[0] = 1 for empty prefix

    for i in range(n):
        max_inv_curr = (i + 1) * i // 2

        new_dp = [0] * (max_inv_curr + 1)

        for j in range(len(dp)):
            if dp[j] == 0:
                continue
            for add in range(i + 1):
                new_j = j + add
                if new_j <= max_inv_curr:
                    new_dp[new_j] = (new_dp[new_j] + dp[j]) % MOD

        dp = new_dp

        # Check requirement for prefix of length i+1 (index i)
        if req_inv[i] != -1:
            required = req_inv[i]
            if required > len(dp) - 1:
                return 0
            if dp[required] == 0:
                return 0
            # Keep only the state with exactly 'required' inversions
            dp = [0] * (required + 1)
            dp[required] = dp[required]

    total_required = req_inv[n - 1]
    if total_required >= len(dp):
        return 0
    return dp[total_required] % MOD
