def countCompleteSubstrings(word: str, k: int):
    n = len(word)
    count = 0

    for d in range(1, 27):
        window_size = d * k
        if window_size > n:
            break

        # Precompute adjacency validity for all positions
        # adj[i] = True if abs(word[i] - word[i-1]) <= 2
        # We need all adjacencies in window to be valid

        # For each window of size window_size, check:
        # 1. Each char in window appears exactly k times
        # 2. All adjacent pairs in window have diff <= 2

        for start in range(n - window_size + 1):
            end = start + window_size - 1

            # Check adjacency
            valid_adj = True
            for i in range(start, end):
                if abs(ord(word[i + 1]) - ord(word[i])) > 2:
                    valid_adj = False
                    break
            if not valid_adj:
                continue

            # Check frequency
            freq = {}
            valid_freq = True
            for i in range(start, end + 1):
                c = word[i]
                freq[c] = freq.get(c, 0) + 1

            for c, f in freq.items():
                if f != k:
                    valid_freq = False
                    break

            if valid_freq:
                count += 1

    return count
