def count(num1: str, num2: str, min_sum: int, max_sum: int):
    MOD = 10**9 + 7

    def digit_sum_count(s: str, min_s: int, max_s: int) -> int:
        """Count numbers x where 0 <= x <= int(s) and min_s <= digit_sum(x) <= max_s"""
        digits = list(map(int, s))
        n = len(digits)

        # dp[pos][sum][tight] = count of ways
        # We use memoization with (pos, current_sum, tight)
        from functools import lru_cache

        @lru_cache(maxsize=None)
        def dp(pos: int, current_sum: int, tight: bool) -> int:
            if pos == n:
                return 1 if min_s <= current_sum <= max_s else 0

            upper = digits[pos] if tight else 9
            total = 0
            for d in range(upper + 1):
                new_tight = tight and (d == digits[pos])
                total += dp(pos + 1, current_sum + d, new_tight)
            return total % MOD

        return dp(0, 0, True)

    def count_up_to(num_str: str, min_s: int, max_s: int) -> int:
        """Count numbers x where 0 <= x <= int(num_str) and min_s <= digit_sum(x) <= max_s"""
        return digit_sum_count(num_str, min_s, max_s)

    # We want count(num1 <= x <= num2) with digit_sum in [min_sum, max_sum]
    # = count(0 <= x <= num2) - count(0 <= x <= num1 - 1)

    # Convert num1 - 1 to string
    def subtract_one(s: str) -> str:
        """Return s - 1 as string, assuming s >= '1'"""
        digits = list(map(int, s))
        i = len(digits) - 1
        while i >= 0:
            if digits[i] > 0:
                digits[i] -= 1
                break
            else:
                digits[i] = 9
                i -= 1
        # Remove leading zeros
        result = ''.join(map(str, digits))
        # Remove leading zeros but keep at least one digit
        result = result.lstrip('0')
        if result == '':
            result = '0'
        return result

    if num1 == "0":
        return count_up_to(num2, min_sum, max_sum)

    num1_minus_1 = subtract_one(num1)

    # If num1 is "0", then num1 - 1 is negative, but constraints say num1 >= 1
    # So num1_minus_1 >= "0"

    result = (count_up_to(num2, min_sum, max_sum) - count_up_to(num1_minus_1, min_sum, max_sum)) % MOD
    return result
