def minimumDifference(nums: List[int], k: int):
    n = len(nums)
    ans = float('inf')

    # For each starting position, track the distinct OR values of subarrays starting there
    # OR values are non-decreasing and there are at most ~30 distinct values per start (since bits only get added)

    # Efficient approach: for each right endpoint, track all distinct OR values of subarrays ending at that position
    # Use a set/list to maintain distinct OR values

    current_ors = set()
    for num in nums:
        new_ors = {num}
        for val in current_ors:
            new_ors.add(val | num)
        current_ors = new_ors
        for val in current_ors:
            diff = abs(k - val)
            if diff < ans:
                ans = diff
            if ans == 0:
                return 0

    return ans
